<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor\UserInvitationAcceptedByAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationAcceptedByAccessor trait.
 *
 * Covers null default, string/VO assignment via withAcceptedBy,
 * getAcceptedBy/acceptedBy accessors, and isAcceptedByChanged with/without original.
 */
class UserInvitationAcceptedByAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAcceptedBy creates a new instance with the AcceptedBy set
     * from a string value, and getAcceptedBy returns the primitive string.
     */
    public function testWithAcceptedByFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationAcceptedByAccessorUnitTest();

        // Act
        $result = $holder->withAcceptedBy(new UserRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRef('one'), $result->getAcceptedBy());
    }
    /**
     * Asserts that withacceptedBy has access to the value object
     * from a string value, and getAcceptedBy returns the primitive string.
     */
    public function testWithAcceptedByFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationAcceptedByAccessorUnitTest();

        // Act
        $result = $holder->withAcceptedBy(new UserRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRef('one'), $result->acceptedBy()->value());
    }
    public function testChangedAcceptedBy(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationAcceptedByAccessorUnitTest();
        $original = $holder->withAcceptedBy(new UserRef('one'));
        $same = $holder->withAcceptedBy(new UserRef('one'));
        $modified = $holder->withAcceptedBy(new UserRef('other'));

        // Act
        $unchanged = $holder->isAcceptedByChanged();
        $withSame = $original->isAcceptedByChanged($same);
        $withDiferent = $original->isAcceptedByChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserInvitationAcceptedByAccessorUnitTest
{
    use UserInvitationAcceptedByAccessor;
}
